// src/LoginRegister.js
import React, { useState } from "react";
import axios from "axios";
import { useNavigate } from "react-router-dom";
import { useAuth } from "./auth";

function LoginRegister() {
  const navigate = useNavigate();
  const { setUser } = useAuth();

  const [isLogin, setIsLogin] = useState(true);
  const [form, setForm] = useState({
    username: "",
    password: "",
    email: "",
    confirmPassword: "",
    pin: "",
    loginType: "password",
  });
  const [error, setError] = useState("");

  const handleChange = (e) => {
    setForm({ ...form, [e.target.name]: e.target.value });
    setError("");
  };

  const submitForm = async (e) => {
    e.preventDefault();

    if (!form.username || !form.password || (!isLogin && !form.email)) {
      setError("❌ All fields are required!");
      return;
    }
    if (!isLogin && form.password !== form.confirmPassword) {
      setError("❌ Passwords do not match!");
      return;
    }

    try {
      if (isLogin) {
        const res = await axios.post("http://localhost:5000/api/login", {
          username: form.username,
          password: form.password,
        });
        // Expect res.data = { token, user }
        localStorage.setItem("token", res.data.token);
        setUser(res.data.user);
        navigate("/role");
      } else {
        await axios.post("http://localhost:5000/api/register", form);
        alert("✅ Registration successful! Please login.");
        setIsLogin(true);
        setForm({
          username: "",
          password: "",
          email: "",
          confirmPassword: "",
          pin: "",
          loginType: "password",
        });
      }
    } catch (err) {
      setError(`❌ ${err.response?.data?.msg || "Server error"}`);
    }
  };

  return (
    <div className="flex h-screen items-center justify-center bg-gradient-to-r from-indigo-500 via-purple-500 to-pink-500 p-6">
      <div className="bg-white shadow-2xl p-8 rounded-3xl w-96">
        <h2 className="text-3xl font-bold text-center mb-6 text-purple-700">
          {isLogin ? "Login" : "Register"}
        </h2>

        {error && (
          <div className="bg-red-100 text-red-700 p-2 rounded mb-4 text-center font-medium">
            {error}
          </div>
        )}

        <form onSubmit={submitForm}>
          {!isLogin && (
            <input
              name="email"
              value={form.email}
              onChange={handleChange}
              placeholder="Email"
              className="w-full p-3 mb-3 border rounded-lg focus:ring-2 focus:ring-purple-400"
            />
          )}

          <input
            name="username"
            value={form.username}
            onChange={handleChange}
            placeholder="Username"
            className="w-full p-3 mb-3 border rounded-lg focus:ring-2 focus:ring-purple-400"
          />

          <input
            type="password"
            name="password"
            value={form.password}
            onChange={handleChange}
            placeholder="Password"
            className="w-full p-3 mb-3 border rounded-lg focus:ring-2 focus:ring-purple-400"
          />

          {!isLogin && (
            <>
              <input
                type="password"
                name="confirmPassword"
                value={form.confirmPassword}
                onChange={handleChange}
                placeholder="Confirm Password"
                className="w-full p-3 mb-3 border rounded-lg focus:ring-2 focus:ring-purple-400"
              />
              <input
                name="pin"
                value={form.pin}
                onChange={handleChange}
                placeholder="Login PIN (optional)"
                className="w-full p-3 mb-3 border rounded-lg focus:ring-2 focus:ring-purple-400"
              />
              <select
                name="loginType"
                value={form.loginType}
                onChange={handleChange}
                className="w-full p-3 mb-3 border rounded-lg focus:ring-2 focus:ring-purple-400"
              >
                <option value="password">Password</option>
                <option value="pin">PIN</option>
                <option value="voice">Voice</option>
              </select>
            </>
          )}

          <button
            type="submit"
            className="w-full bg-purple-600 text-white p-3 rounded-lg hover:bg-purple-800 transition-colors duration-300 font-semibold"
          >
            {isLogin ? "Login" : "Register"}
          </button>
        </form>

        <p className="mt-4 text-center text-sm text-gray-600">
          {isLogin ? "Don't have an account?" : "Already have an account?"}{" "}
          <span
            onClick={() => {
              setIsLogin(!isLogin);
              setError("");
            }}
            className="text-indigo-600 cursor-pointer font-semibold hover:underline"
          >
            {isLogin ? "Register" : "Login"}
          </span>
        </p>
      </div>
    </div>
  );
}

export default LoginRegister;
